package io.xeros.solo;
import io.xeros.*;import io.xeros.content.achievement_diary.*;import io.xeros.content.achievement_diary.DifficultyAchievementDiary.EntryDifficulty;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.util.*;
@SuppressWarnings({"rawtypes","unchecked"}) public class Diaries70Check {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){Player p=ClassicQuests70Check.actor();p.setLoginName("diary70qa");p.setDisplayName("Diary70qa");return p;}static int[] rewards(StatefulAchievementDiary d){String n=d.getClass().getSimpleName();int base=n.startsWith("Karamja")?11136:n.startsWith("Varrock")?13104:n.startsWith("Wilderness")?13108:n.startsWith("Morytania")?13112:n.startsWith("Falador")?13117:n.startsWith("Ardougne")?13121:n.startsWith("Lumbridge")?13125:n.startsWith("Fremennik")?13129:n.startsWith("Desert")?13133:n.startsWith("Kandarin")?13137:13141;return base==11136?new int[]{11136,11138,11140,13103}:new int[]{base,base+1,base+2,base+3};}
 static void claim(StatefulAchievementDiary d)throws Exception{d.getClass().getMethod("claimReward").invoke(d);}
 static Set entries(StatefulAchievementDiary d,EntryDifficulty t){return t==EntryDifficulty.EASY?d.getEasy():t==EntryDifficulty.MEDIUM?d.getMedium():t==EntryDifficulty.HARD?d.getHard():d.getElite();}
 public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();Player p=actor();int count=0,tasks=0;
 for(StatefulAchievementDiary d:p.getDiaryManager().getAll()){int[] ids=rewards(d);claim(d);ok(!d.hasClaimed(EntryDifficulty.EASY),"Unfinished diary claim");for(Object e:entries(d,EntryDifficulty.MEDIUM))d.nonNotifyComplete((Enum)e);claim(d);ok(!d.hasClaimed(EntryDifficulty.MEDIUM),"Skipping easy tier");
 for(EntryDifficulty t:EntryDifficulty.values()){Set set=entries(d,t);for(Object e:set){Enum task=(Enum)e;if(!d.hasDone(task)){d.setAchievementStage(task,0,false);ok(!d.hasDone(task),"Zero completed a task "+task);d.progress(task,false,-1);ok(!d.hasDone(task),"Negative completed task "+task);d.setAchievementStage(task,Integer.MAX_VALUE,false);}ok(d.hasDone(task),"Task completion "+task);tasks++;}p.isDead=true;claim(d);ok(!d.hasClaimed(t),"Dead reward claim");p.isDead=false;claim(d);ok(d.hasClaimed(t)&&p.getItems().getItemCount(ids[t.ordinal()],false)==1,"Tier reward "+d.getName()+" "+t+" id "+ids[t.ordinal()]);count++;}
 claim(d);ok(p.getItems().getItemCount(ids[3],false)==1,"Duplicate highest reward");ok(d.getProgressText(EntryDifficulty.EASY).equals(d.getEasy().size()+"/"+d.getEasy().size()),"Completion text "+d.getName());System.out.println("DIARY_ALL_FOUR_TIERS_CLAIM_ORDER_DEATH_GUARD_REWARD_IDS_NO_DUPLICATE_PASS "+d.getName());}
 p.getDiaryManager().setDiariesCompleted();ok(p.diariesCompleted==11,"Diary region recount");for(int i=0;i<5;i++)p.getDiaryManager().setDiariesCompleted();ok(p.diariesCompleted==11,"Diary count accumulates");ok(count==44,"44 tiers");ok(PlayerSave.saveGameInstant(p),"Real diary save");Player q=actor();ok(PlayerSave.loadGame(q,"diary70qa","IsolatedAudit",true).toString().equals("SUCCESS"),"Diary reload");q.getDiaryManager().setDiariesCompleted();ok(q.diariesCompleted==11,"Reload counter");for(StatefulAchievementDiary d:q.getDiaryManager().getAll()){for(EntryDifficulty t:EntryDifficulty.values())ok(d.hasDone(t)&&d.hasClaimed(t),"Saved tier "+d.getName()+" "+t);for(int id:rewards(d))ok(q.getItems().getItemCount(id,false)==1,"Saved inventory/bank reward "+id);claim(d);ok(q.getItems().getItemCount(rewards(d)[3],false)==1,"Repeat reward after reload");}
 System.out.println("DIARIES70_"+tasks+"_TASKS_44_TIERS_FULL_INVENTORY_BANK_DELIVERY_NATIVE_SAVE_RELOAD_IDEMPOTENCE_PASS");System.exit(0);}
}